import{_ as t,o as d,c as a,a2 as o}from"./chunks/framework.DoCD98hS.js";const p=JSON.parse('{"title":"模块总览","description":"","frontmatter":{},"headers":[],"relativePath":"modules/index.md","filePath":"modules/index.md","lastUpdated":1794734946000}'),r={name:"modules/index.md"};function c(l,e,i,s,n,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="模块总览" tabindex="-1">模块总览 <a class="header-anchor" href="#模块总览" aria-label="Permalink to &quot;模块总览&quot;">​</a></h1><p>先按职责找目录，再选择框架或具体组件体系。此处提供分类地图，进入专题后查看方法、组件与模板改造骨架。</p><table tabindex="0"><thead><tr><th>模块类别</th><th>负责什么</th><th>入口</th></tr></thead><tbody><tr><td><code>libs-*</code></td><td>基础能力、工具、框架或专题运行时</td><td><a href="./libs.html">基础库</a></td></tr><tr><td><code>comps-*</code></td><td>可复用组件、组件体系与领域能力</td><td><a href="./components.html">组件包</a></td></tr><tr><td><code>demo-*</code></td><td>验证组件加载与消费方式的轻量宿主</td><td><a href="./demos.html">消费示例</a></td></tr><tr><td><code>tpl-*</code></td><td>组合基础库与组件的完整应用模板</td><td><a href="./templates.html">应用模板</a></td></tr><tr><td><code>docs-*</code> / <code>service-*</code></td><td>文档入口与配套服务</td><td><a href="./docs-and-services.html">文档与服务</a></td></tr></tbody></table><h2 id="两条阅读路径" tabindex="-1">两条阅读路径 <a class="header-anchor" href="#两条阅读路径" aria-label="Permalink to &quot;两条阅读路径&quot;">​</a></h2><ul><li><strong>接入组件</strong>：选 <code>comps-*</code> → 找对应 <code>demo-*</code> → 确认运行时和样式要求 → 选择预加载或懒加载。</li><li><strong>组装应用</strong>：选 <code>tpl-*</code> → 了解对应的 <code>libs-*</code> / <code>comps-*</code> → 按业务需要添加模块。</li></ul><h2 id="不要只按前缀判断加载方式" tabindex="-1">不要只按前缀判断加载方式 <a class="header-anchor" href="#不要只按前缀判断加载方式" aria-label="Permalink to &quot;不要只按前缀判断加载方式&quot;">​</a></h2><p><code>libs-core</code> 是宿主侧公共工具，并不是远程组件；Bag 插件目前以普通库产物供宿主使用；<code>tpl-vue3-datav-mf-station</code> 是独立静态大屏，不依赖远程组件包。具体以各包入口和构建配置为准。</p><h2 id="收敛方向" tabindex="-1">收敛方向 <a class="header-anchor" href="#收敛方向" aria-label="Permalink to &quot;收敛方向&quot;">​</a></h2><p>跨框架通用方法优先进入 <code>libs-core</code>。确实依赖 Vue 2、Vue 3 或 React 的封装，分别进入已有的 <code>libs-core-vue2</code>、<code>libs-core-vue3</code>、<code>libs-core-react</code>。详见<a href="./../guide/core.html">核心分层</a>。</p><h2 id="专题如何组织" tabindex="-1">专题如何组织 <a class="header-anchor" href="#专题如何组织" aria-label="Permalink to &quot;专题如何组织&quot;">​</a></h2><p>同一能力的框架版本、同一开源体系的基础库 / 组件 / 模板合并成一篇。各分类表均可进入对应专题，后续直接在占位章节补充，避免重复拆页。</p><ul><li>基础能力：Core、Leva、Utils / Lodash。</li><li>通用组件：基础组件、Element、Ant Design、TDesign。</li><li>领域组件：金融、医疗、工业、选择器、热门交互、DataV。</li><li>开源体系与模板：Pure、Art、Fan、Vben、Bag、qiankun 2、MF Station。</li></ul><p>每篇的“待补内容”保留完整 API、示例和逐文件改造位置，当前仅列已核对的代表性能力。</p>',13)])])}const u=t(r,[["render",c]]);export{p as __pageData,u as default};
